window.ENGLISH_COURSE={categories:[["basic","基礎","10単元・生活英語の土台"],["intermediate","中級","文をつないで説明する"],["daily","日常","暮らしで自然に使う"],["travel","旅行","移動・宿泊・食事・トラブル"],["work","仕事","確認・報告・安全・設備"],["advanced","上級","理由・意見・調整"],["master","超級","即興・言い換え・交渉"]],lessons:[
{id:"b01",scene:"greeting",cat:"basic",title:"1. あいさつ",items:[
{en:"Good morning.",ja:"おはようございます。",a:"Good morning.",b:"Good morning! How are you?"},
{en:"How are you?",ja:"元気ですか？",a:"How are you?",b:"I'm good, thank you."},
{en:"I'm doing well, thank you.",ja:"元気です、ありがとう。",a:"How are you doing?",b:"I'm doing well, thank you."},
{en:"See you later.",ja:"またあとで。",a:"I'm leaving now.",b:"Okay. See you later."},
{en:"Hello. Nice to see you.",ja:"こんにちは。会えてうれしいです。",a:"Hello!",b:"Hello. Nice to see you."},
{en:"Have a good day.",ja:"よい一日を。",a:"I'm heading out.",b:"Okay. Have a good day."}]},
{id:"b02",scene:"introduction",cat:"basic",title:"2. 自己紹介",items:[
{en:"My name is Shohei.",ja:"私の名前はショウヘイです。",a:"What's your name?",b:"My name is Shohei."},
{en:"I'm from Japan.",ja:"日本から来ました。",a:"Where are you from?",b:"I'm from Japan."},
{en:"I live in Aichi.",ja:"愛知に住んでいます。",a:"Where do you live?",b:"I live in Aichi."},
{en:"Nice to meet you.",ja:"はじめまして。",a:"Nice to meet you.",b:"Nice to meet you, too."},
{en:"I work in maintenance.",ja:"保全の仕事をしています。",a:"What do you do?",b:"I work in maintenance."},
{en:"I like motorcycles.",ja:"バイクが好きです。",a:"What do you like?",b:"I like motorcycles."}]},
{id:"b03",scene:"response",cat:"basic",title:"3. 基本の返事",items:[
{en:"Yes, that's right.",ja:"はい、その通りです。",a:"Is this correct?",b:"Yes, that's right."},
{en:"No, not yet.",ja:"いいえ、まだです。",a:"Are you ready?",b:"No, not yet."},
{en:"I'm not sure.",ja:"よく分かりません。",a:"Do you know?",b:"I'm not sure."},
{en:"I understand.",ja:"分かりました。",a:"Does that make sense?",b:"Yes, I understand."},
{en:"Okay, I got it.",ja:"はい、分かりました。",a:"Please check this first.",b:"Okay, I got it."},
{en:"Maybe.",ja:"たぶん。",a:"Will it rain today?",b:"Maybe."}]},
{id:"b04",scene:"clarification",cat:"basic",title:"4. 聞き返す・お願いする",items:[
{en:"Could you say that again?",alt:"Could you repeat that, please?",ja:"もう一度言ってもらえますか？",a:"Did you understand?",b:"Could you say that again?"},
{en:"Please speak more slowly.",ja:"もう少しゆっくり話してください。",a:"Is this speed okay?",b:"Please speak more slowly."},
{en:"What does this mean?",ja:"これはどういう意味ですか？",a:"Do you know this word?",b:"No. What does this mean?"},
{en:"Could you show me?",ja:"見せてもらえますか？",a:"Do you know how to do it?",b:"Not yet. Could you show me?"},
{en:"Could you write it down?",ja:"書いてもらえますか？",a:"Is the name clear?",b:"Not really. Could you write it down?"},
{en:"How do you spell that?",ja:"どう綴りますか？",a:"My name is Chris.",b:"How do you spell that?"}]},
{id:"b05",scene:"schedule",cat:"basic",title:"5. 時間・予定",items:[
{en:"What time is it?",ja:"何時ですか？",a:"What time is it?",b:"It's three o'clock."},
{en:"What time does it start?",ja:"何時に始まりますか？",a:"The meeting is today.",b:"What time does it start?"},
{en:"I'm free this afternoon.",ja:"今日の午後は空いています。",a:"Are you busy this afternoon?",b:"No. I'm free this afternoon."},
{en:"See you tomorrow.",ja:"また明日。",a:"I'm going home now.",b:"Okay. See you tomorrow."},
{en:"I'm available after three.",ja:"3時以降なら空いています。",a:"When are you available?",b:"I'm available after three."},
{en:"Can we meet tomorrow morning?",ja:"明日の朝、会えますか？",a:"When should we meet?",b:"Can we meet tomorrow morning?"}]},
{id:"b06",scene:"directions",cat:"basic",title:"6. 場所・道案内",items:[
{en:"Where is the station?",ja:"駅はどこですか？",a:"Can I help you?",b:"Yes. Where is the station?"},
{en:"Is it far from here?",ja:"ここから遠いですか？",a:"The station is that way.",b:"Is it far from here?"},
{en:"Turn left at the corner.",ja:"角を左に曲がってください。",a:"How do I get there?",b:"Turn left at the corner."},
{en:"It's next to the bank.",ja:"銀行の隣です。",a:"Where is the pharmacy?",b:"It's next to the bank."},{en:"Go straight for two blocks.",ja:"2ブロックまっすぐ進んでください。",a:"How do I get to the station?",b:"Go straight for two blocks."},{en:"Is this the right way?",ja:"この道で合っていますか？",a:"Where are you going?",b:"To the station. Is this the right way?"}]},
{id:"b07",scene:"shopping",cat:"basic",title:"7. 買い物",items:[
{en:"How much is this?",ja:"これはいくらですか？",a:"Can I help you?",b:"Yes. How much is this?"},
{en:"Do you have a larger size?",ja:"もっと大きいサイズはありますか？",a:"How does it fit?",b:"It's small. Do you have a larger size?"},
{en:"I'll take this one.",ja:"これにします。",a:"Would you like this one?",b:"Yes. I'll take this one."},
{en:"Can I pay by card?",ja:"カードで払えますか？",a:"How would you like to pay?",b:"Can I pay by card?"},{en:"Can I try this on?",ja:"試着してもいいですか？",a:"Do you like this shirt?",b:"Yes. Can I try this on?"},{en:"Do you have this in black?",ja:"これの黒はありますか？",a:"Which color would you like?",b:"Do you have this in black?"}]},
{id:"b08",scene:"restaurant",cat:"basic",title:"8. 食事・注文",items:[
{en:"I'd like some coffee, please.",ja:"コーヒーをお願いします。",a:"What would you like?",b:"I'd like some coffee, please."},
{en:"Could I see the menu, please?",ja:"メニューを見せてもらえますか？",a:"Are you ready to order?",b:"Not yet. Could I see the menu, please?"},
{en:"What do you recommend?",ja:"おすすめは何ですか？",a:"Would you like something to eat?",b:"Yes. What do you recommend?"},
{en:"Could I have the check, please?",ja:"お会計をお願いします。",a:"Anything else?",b:"No, thank you. Could I have the check, please?"},{en:"I'd like this, please.",ja:"これをお願いします。",a:"Are you ready to order?",b:"Yes. I'd like this, please."},{en:"Could I have some water?",ja:"お水をもらえますか？",a:"Anything to drink?",b:"Could I have some water?"}]},
{id:"b09",scene:"transport",cat:"basic",title:"9. 移動・交通",items:[
{en:"How do I get there?",ja:"そこへはどう行けばいいですか？",a:"Where are you going?",b:"I'm going to the museum. How do I get there?"},
{en:"Which train should I take?",ja:"どの電車に乗ればいいですか？",a:"Where are you going?",b:"Nagoya. Which train should I take?"},
{en:"Does this bus go to the station?",ja:"このバスは駅に行きますか？",a:"Can I help you?",b:"Yes. Does this bus go to the station?"},
{en:"I'd like to go to this address.",ja:"この住所までお願いします。",a:"Where would you like to go?",b:"I'd like to go to this address."},{en:"Where can I buy a ticket?",ja:"切符はどこで買えますか？",a:"Do you need a ticket?",b:"Yes. Where can I buy a ticket?"},{en:"What time is the next train?",ja:"次の電車は何時ですか？",a:"The train just left.",b:"What time is the next train?"}]},
{id:"b10",scene:"help",cat:"basic",title:"10. 困ったとき",items:[
{en:"Could you help me?",ja:"手伝ってもらえますか？",a:"Are you okay?",b:"I need some help. Could you help me?"},
{en:"I can't find my phone.",ja:"携帯電話が見つかりません。",a:"What's wrong?",b:"I can't find my phone."},
{en:"I don't feel well.",ja:"気分がよくありません。",a:"Are you okay?",b:"No. I don't feel well."},
{en:"Where is the nearest hospital?",ja:"一番近い病院はどこですか？",a:"Do you need a doctor?",b:"Yes. Where is the nearest hospital?"},{en:"I need a doctor.",ja:"医者が必要です。",a:"Are you feeling okay?",b:"No. I need a doctor."},{en:"I lost my wallet.",ja:"財布をなくしました。",a:"What's the problem?",b:"I lost my wallet."}]},

{id:"i01",cat:"intermediate",title:"1. 状況を説明する",items:[
{en:"The machine stopped suddenly.",ja:"機械が突然停止しました。",a:"What happened?",b:"The machine stopped suddenly."},
{en:"I was working when the alarm went off.",ja:"作業中にアラームが鳴りました。",a:"When did the alarm go off?",b:"I was working when the alarm went off."},
{en:"It was working normally this morning.",ja:"今朝は正常に動いていました。",a:"Was there a problem this morning?",b:"No. It was working normally this morning."}]},
{id:"i02",cat:"intermediate",title:"2. 原因を推測する",items:[
{en:"I think the sensor may be causing the problem.",ja:"センサーが問題の原因かもしれないと思います。",a:"What do you think is wrong?",b:"I think the sensor may be causing the problem."},
{en:"It could be a loose connection.",ja:"接続の緩みかもしれません。",a:"What could be causing it?",b:"It could be a loose connection."},
{en:"I'm not sure yet, so I'll check it first.",ja:"まだ分からないので、まず確認します。",a:"Do you know the cause?",b:"I'm not sure yet, so I'll check it first."}]},
{id:"i03",cat:"intermediate",title:"3. 順序立てて話す",items:[
{en:"First, I'll check the power supply.",ja:"まず電源を確認します。",a:"What will you check first?",b:"First, I'll check the power supply."},
{en:"Then, I'll check the sensor.",ja:"次にセンサーを確認します。",a:"What will you do next?",b:"Then, I'll check the sensor."},
{en:"After that, I'll test the machine again.",ja:"そのあと、もう一度機械をテストします。",a:"And after that?",b:"After that, I'll test the machine again."}]},

{id:"d01",cat:"daily",title:"1. 家での会話",items:[
{en:"I'll be back soon.",ja:"すぐ戻ります。",a:"Are you going out?",b:"Yes. I'll be back soon."},
{en:"I'm going to make some coffee.",ja:"コーヒーを入れます。",a:"What are you doing?",b:"I'm going to make some coffee."},
{en:"Do you need anything?",ja:"何か必要なものはありますか？",a:"I'm going to the store.",b:"Okay. Do you need anything?"}]},
{id:"d02",cat:"daily",title:"2. 天気と予定",items:[
{en:"It looks like it's going to rain.",ja:"雨が降りそうです。",a:"How's the weather?",b:"It looks like it's going to rain."},
{en:"Let's go out after lunch.",ja:"昼食のあと出かけましょう。",a:"When should we go?",b:"Let's go out after lunch."},
{en:"I might stay home today.",ja:"今日は家にいるかもしれません。",a:"Are you going out today?",b:"I might stay home today."}]},
{id:"d03",cat:"daily",title:"3. 電話の基本",items:[
{en:"I'll call you later.",ja:"あとで電話します。",a:"Can you talk now?",b:"I'm busy right now. I'll call you later."},
{en:"I just sent you a message.",ja:"今メッセージを送りました。",a:"Did you send the address?",b:"Yes. I just sent you a message."},
{en:"Sorry, I missed your call.",ja:"電話に出られなくてすみません。",a:"I called you earlier.",b:"Sorry, I missed your call."}]},

{id:"t01",scene:"hotel",cat:"travel",title:"1. ホテルの基本",items:[
{en:"I have a reservation.",ja:"予約しています。",a:"How can I help you?",b:"I have a reservation."},
{en:"Could I check in early?",ja:"早めにチェックインできますか？",a:"Check-in starts at three.",b:"Could I check in early?"},
{en:"What time is check-out?",ja:"チェックアウトは何時ですか？",a:"Is there anything else?",b:"Yes. What time is check-out?"}]},
{id:"t02",scene:"airport",cat:"travel",title:"2. 空港で場所・便を確認",items:[
{en:"Where is the check-in counter?",ja:"チェックインカウンターはどこですか？",a:"Can I help you?",b:"Yes. Where is the check-in counter?"},
{en:"Which gate does the flight leave from?",ja:"この便は何番ゲートから出発しますか？",a:"What would you like to know?",b:"Which gate does the flight leave from?"},
{en:"My flight has been delayed.",ja:"私の便が遅れています。",a:"Why are you still here?",b:"My flight has been delayed."}]},
{id:"t03",scene:"restaurant",cat:"travel",title:"3. レストラン",items:[
{en:"Do you have a table for two?",ja:"2人ですが席はありますか？",a:"Good evening.",b:"Good evening. Do you have a table for two?"},
{en:"Does this contain nuts?",ja:"これにはナッツが入っていますか？",a:"Would you like to order this?",b:"Maybe. Does this contain nuts?"},
{en:"Everything was delicious.",ja:"どれもおいしかったです。",a:"How was your meal?",b:"Everything was delicious."}]},
{id:"t04",scene:"trouble",cat:"travel",title:"4. トラブル",items:[
{en:"I think I'm lost.",ja:"道に迷ったようです。",a:"Do you need help?",b:"Yes. I think I'm lost."},
{en:"My luggage hasn't arrived.",ja:"荷物が出てきません。",a:"What's the problem?",b:"My luggage hasn't arrived."},
{en:"Could you call a taxi for me?",ja:"タクシーを呼んでもらえますか？",a:"How can I help?",b:"Could you call a taxi for me?"}]},

{id:"w01",scene:"report",cat:"work",title:"1. 確認と報告",items:[
{en:"Let me check it first.",ja:"まず確認させてください。",a:"Can you fix it now?",b:"Let me check it first."},
{en:"The pressure is lower than usual.",ja:"圧力が通常より低いです。",a:"What did you notice?",b:"The pressure is lower than usual."},
{en:"I'll let you know when I find the cause.",ja:"原因が分かったら知らせます。",a:"Do you know what's wrong?",b:"Not yet. I'll let you know when I find the cause."}]},
{id:"w02",scene:"safety",cat:"work",title:"2. 安全確認",items:[
{en:"Please turn off the power first.",ja:"まず電源を切ってください。",a:"Can I open this panel?",b:"Please turn off the power first."},
{en:"Make sure the machine has stopped completely.",ja:"機械が完全に停止したことを確認してください。",a:"Can I start working now?",b:"Make sure the machine has stopped completely."},
{en:"We need to check the area before restarting.",ja:"再起動する前に周囲を確認する必要があります。",a:"Can we restart it now?",b:"We need to check the area before restarting."}]},
{id:"w03",scene:"abnormality",cat:"work",title:"3. 異常を伝える",items:[
{en:"There's an unusual noise coming from the motor.",ja:"モーターから異音がしています。",a:"What did you notice?",b:"There's an unusual noise coming from the motor."},
{en:"The temperature is higher than normal.",ja:"温度が通常より高いです。",a:"Is the temperature okay?",b:"No. The temperature is higher than normal."},
{en:"There's a small leak near the valve.",ja:"バルブ付近に少量の漏れがあります。",a:"Did you find anything?",b:"Yes. There's a small leak near the valve."}]},
{id:"w04",scene:"handover",cat:"work",title:"4. 作業を引き継ぐ",items:[
{en:"I've already checked the sensor.",ja:"センサーはすでに確認しました。",a:"Have you checked the sensor?",b:"Yes. I've already checked the sensor."},
{en:"The problem hasn't been fixed yet.",ja:"問題はまだ直っていません。",a:"Is the machine ready?",b:"No. The problem hasn't been fixed yet."},
{en:"Please keep an eye on the pressure.",ja:"圧力を注意して見ておいてください。",a:"What should I watch?",b:"Please keep an eye on the pressure."}]},

{id:"a01",cat:"advanced",title:"1. 理由を説明する",items:[
{en:"The main reason is that we need more information.",ja:"主な理由は、さらに情報が必要だからです。",a:"Why can't we decide yet?",b:"The main reason is that we need more information."},
{en:"I chose this option because it's safer and easier to maintain.",ja:"より安全で保全しやすいため、この方法を選びました。",a:"Why did you choose this option?",b:"I chose this option because it's safer and easier to maintain."}]},
{id:"a02",cat:"advanced",title:"2. 意見を調整する",items:[
{en:"I see your point, but I have one concern.",ja:"言いたいことは分かりますが、一つ懸念があります。",a:"I think we should restart it now.",b:"I see your point, but I have one concern."},
{en:"I agree in principle, but we should confirm the data first.",ja:"基本的には賛成ですが、まずデータを確認すべきです。",a:"Do you agree with the plan?",b:"I agree in principle, but we should confirm the data first."}]},

{id:"m01",cat:"master",title:"1. 意図を確認する",items:[
{en:"Let me make sure I understand what you mean.",ja:"あなたの意図を正しく理解できているか確認させてください。",a:"Do you understand my point?",b:"Let me make sure I understand what you mean."},
{en:"If I understand correctly, you're suggesting that we wait.",ja:"正しく理解していれば、待つことを提案しているのですね。",a:"What do you think I'm suggesting?",b:"If I understand correctly, you're suggesting that we wait."}]},
{id:"m02",cat:"master",title:"2. 言い換えて伝える",items:[
{en:"Let me put it another way.",alt:"Let me rephrase that.",ja:"別の言い方をします。",a:"I'm not sure I understand.",b:"Let me put it another way."},
{en:"In other words, the issue isn't the motor itself.",ja:"つまり、問題はモーターそのものではありません。",a:"So the motor is broken?",b:"Not exactly. In other words, the issue isn't the motor itself."}]},
{id:"i04",cat:"intermediate",title:"4. 経験を話す",items:[{en:"I've been there several times.",ja:"そこには何度か行ったことがあります。",a:"Have you been there before?",b:"Yes. I've been there several times."},{en:"I've never tried it before.",ja:"今までそれを試したことがありません。",a:"Have you tried this?",b:"No. I've never tried it before."},{en:"I learned how to do it last year.",ja:"去年そのやり方を覚えました。",a:"When did you learn this?",b:"I learned how to do it last year."}]},
{id:"i05",cat:"intermediate",title:"5. 比較して選ぶ",items:[{en:"This one is easier to use.",ja:"こちらのほうが使いやすいです。",a:"Which one do you prefer?",b:"This one is easier to use."},{en:"The other option is cheaper, but it takes longer.",ja:"もう一方は安いですが、時間がかかります。",a:"What about the other option?",b:"The other option is cheaper, but it takes longer."},{en:"I think this is the better choice.",ja:"こちらのほうがよい選択だと思います。",a:"Which should we choose?",b:"I think this is the better choice."}]},
{id:"i06",cat:"intermediate",title:"6. 理由を添える",items:[{en:"I stayed home because I was tired.",ja:"疲れていたので家にいました。",a:"Why didn't you go out?",b:"I stayed home because I was tired."},{en:"I chose it because it was simple.",ja:"簡単だったのでそれを選びました。",a:"Why did you choose it?",b:"I chose it because it was simple."},{en:"That's why I wanted to check first.",ja:"だから先に確認したかったんです。",a:"Why did you wait?",b:"That's why I wanted to check first."}]},
{id:"i07",cat:"intermediate",title:"7. 予定と変更",items:[{en:"I'm planning to go there next week.",ja:"来週そこへ行く予定です。",a:"When are you going?",b:"I'm planning to go there next week."},{en:"We may need to change the schedule.",ja:"予定を変更する必要があるかもしれません。",a:"Is the schedule final?",b:"We may need to change the schedule."},{en:"I'll let you know if anything changes.",ja:"何か変更があれば知らせます。",a:"What if the plan changes?",b:"I'll let you know if anything changes."}]},
{id:"i08",cat:"intermediate",title:"8. 丁寧に頼む",items:[{en:"Would you mind checking this for me?",ja:"これを確認していただけますか？",a:"What do you need?",b:"Would you mind checking this for me?"},{en:"Could you give me a little more time?",ja:"もう少し時間をいただけますか？",a:"Can you finish now?",b:"Could you give me a little more time?"},{en:"I'd appreciate your help.",ja:"手伝っていただけると助かります。",a:"Do you need any help?",b:"Yes. I'd appreciate your help."}]},
{id:"d04",cat:"daily",title:"4. 体調",items:[{en:"I'm a little tired today.",variants:[{q:"How are you feeling now?",r:"I’m a little tired, but I’m okay."},{q:"Do you want to take a break?",r:"Yes, a short break would help."}],ja:"今日は少し疲れています。",a:"How are you feeling?",b:"I'm a little tired today."},{en:"I have a slight headache.",ja:"少し頭が痛いです。",a:"Are you okay?",b:"I have a slight headache."},{en:"I think I need some rest.",ja:"少し休んだほうがよさそうです。",a:"What are you going to do?",b:"I think I need some rest."}]},
{id:"d05",cat:"daily",title:"5. 趣味・休日の基本",items:[{en:"I like going for a ride on weekends.",ja:"週末にツーリングへ行くのが好きです。",a:"What do you do on weekends?",b:"I like going for a ride on weekends."},{en:"I've been watching this series lately.",ja:"最近このシリーズを見ています。",a:"What have you been watching?",b:"I've been watching this series lately."},{en:"I just want to relax today.",ja:"今日はのんびりしたいです。",a:"Any plans for today?",b:"I just want to relax today."}]},
{id:"d06",cat:"daily",title:"6. 家事・買い物",items:[{en:"We need to buy some groceries.",ja:"食料品を買う必要があります。",a:"Do we need anything?",b:"We need to buy some groceries."},{en:"I'll take out the trash.",ja:"ゴミを出してきます。",a:"Can you help me?",b:"Sure. I'll take out the trash."},{en:"We're almost out of milk.",ja:"牛乳がもうほとんどありません。",a:"Do we have enough milk?",b:"No. We're almost out of milk."}]},
{id:"d07",cat:"daily",title:"7. 約束・待ち合わせ",items:[{en:"I'll meet you at the station.",variants:[{q:"Where should we meet?",r:"Let’s meet at the station."},{q:"What time should we meet?",r:"Let’s meet at ten."}],ja:"駅で待ち合わせましょう。",a:"Where should we meet?",b:"I'll meet you at the station."},{en:"I'm running about ten minutes late.",ja:"10分ほど遅れています。",a:"Where are you?",b:"I'm running about ten minutes late."},{en:"Take your time. I'm not in a hurry.",ja:"ゆっくりで大丈夫です。急いでいません。",a:"Sorry I'm late.",b:"Take your time. I'm not in a hurry."}]},
{id:"d08",cat:"daily",title:"8. 雑談",items:[{en:"How was your day?",variants:[{q:"Did anything interesting happen today?",r:"Yes, something funny happened at work."},{q:"Was it a busy day?",r:"Yes, it was pretty busy."}],ja:"今日はどうでしたか？",a:"How was your day?",b:"It was pretty good."},{en:"That sounds interesting.",ja:"それは面白そうですね。",a:"I'm learning something new.",b:"That sounds interesting."},{en:"Really? Tell me more.",ja:"本当？もっと聞かせて。",a:"Something funny happened today.",b:"Really? Tell me more."}]},
{id:"t05",scene:"train",cat:"travel",title:"5. 鉄道・乗り換え",items:[{en:"Do I need to change trains?",variants:[{q:"Which platform should I use?",r:"Use platform three."},{q:"How long does it take to get there?",r:"It takes about twenty minutes."}],alt:"Do I have to transfer?",ja:"乗り換えは必要ですか？",a:"Where are you going?",b:"Do I need to change trains?"},{en:"Which platform should I use?",ja:"何番ホームを使えばいいですか？",a:"What do you need to know?",b:"Which platform should I use?"},{en:"Is this the express train?",ja:"これは急行ですか？",a:"Are you getting on?",b:"Yes. Is this the express train?"}]},
{id:"t06",scene:"sightseeing",cat:"travel",title:"6. 観光",items:[{en:"What time does the museum open?",variants:[{q:"What time does it close?",r:"It closes at five."},{q:"Do I need a ticket?",r:"Yes, you need a ticket to enter."}],ja:"博物館は何時に開きますか？",a:"Are you visiting the museum?",b:"Yes. What time does the museum open?"},{en:"How long does it take to get there?",ja:"そこまでどのくらい時間がかかりますか？",a:"Are you going to the castle?",b:"Yes. How long does it take to get there?"},{en:"Could you take a picture for me?",alt:"Would you mind taking a picture for me?",ja:"写真を撮ってもらえますか？",a:"Do you need help?",b:"Yes. Could you take a picture for me?"}]},
{id:"t07",scene:"shopping",cat:"travel",title:"7. 買い物・免税",items:[{en:"Can I try this on?",variants:[{q:"Do you have this in a larger size?",r:"Yes, I’ll check for you."},{q:"Can I pay by card?",r:"Yes, we accept credit cards."}],ja:"試着してもいいですか？",a:"Would you like to try it?",b:"Yes. Can I try this on?"},{en:"Is this tax-free?",ja:"これは免税ですか？",a:"Are you visiting from abroad?",b:"Yes. Is this tax-free?"},{en:"Could I get a receipt, please?",ja:"レシートをいただけますか？",a:"Anything else?",b:"Could I get a receipt, please?"}]},
{id:"t08",scene:"emergency",cat:"travel",title:"8. 体調・緊急時",items:[{en:"I need to see a doctor.",variants:[{q:"What seems to be the problem?",r:"I’m not feeling well and I have a headache."},{q:"Do you need an ambulance?",r:"No, but I need to see a doctor."}],ja:"医師に診てもらう必要があります。",a:"How can I help?",b:"I need to see a doctor."},{en:"Where can I buy some medicine?",ja:"薬はどこで買えますか？",a:"What are you looking for?",b:"Where can I buy some medicine?"},{en:"Please call an ambulance.",ja:"救急車を呼んでください。",a:"What's wrong?",b:"Please call an ambulance."}]},
{id:"w05",scene:"inspection",cat:"work",title:"5. 点検",items:[{en:"I'll check the oil level first.",variants:[{q:"What else should we inspect?",r:"Let’s check for leaks and unusual noise."},{q:"Is the oil level normal?",r:"Yes, it’s within the normal range."}],ja:"まず油量を確認します。",a:"What will you check first?",b:"I'll check the oil level first."},{en:"The reading is within the normal range.",ja:"測定値は正常範囲内です。",a:"How does the reading look?",b:"The reading is within the normal range."},{en:"I found no visible damage.",ja:"目視できる損傷はありませんでした。",a:"Did you find any damage?",b:"No. I found no visible damage."}]},
{id:"w06",scene:"pressure",cat:"work",title:"6. 漏れ・圧力",items:[{en:"The pressure keeps dropping.",variants:[{q:"Where should we check for a leak?",r:"Let’s check the fittings and seals first."},{q:"Should we measure the pressure again?",r:"Yes, let’s measure it again."}],alt:"The pressure is continuing to fall.",ja:"圧力が下がり続けています。",a:"What's happening to the pressure?",b:"The pressure keeps dropping."},{en:"There may be a leak in the line.",variants:[{q:"Can you see where it's leaking?",r:"It looks like it’s leaking near the fitting."},{q:"Should we shut the line down first?",r:"Yes, let’s isolate it before checking."}],alt:"The line may be leaking.",ja:"配管に漏れがあるかもしれません。",a:"What could be causing it?",b:"There may be a leak in the line."},{en:"Let's check the fittings and seals.",ja:"継手とシールを確認しましょう。",a:"What should we check?",b:"Let's check the fittings and seals."}]},
{id:"w07",scene:"cooling",cat:"work",title:"7. 温度・冷却",items:[{en:"The outlet temperature is too high.",variants:[{q:"What is the inlet temperature?",r:"The inlet temperature is within the normal range."},{q:"Is the cooling water flowing normally?",r:"We need to check the flow first."}],alt:"The temperature at the outlet is too high.",ja:"出口温度が高すぎます。",a:"What did you notice?",b:"The outlet temperature is too high."},{en:"The cooling water may not be flowing properly.",ja:"冷却水が正常に流れていない可能性があります。",a:"What could be wrong?",b:"The cooling water may not be flowing properly."},{en:"Let's compare the inlet and outlet temperatures.",ja:"入口と出口の温度を比較しましょう。",a:"What should we do next?",b:"Let's compare the inlet and outlet temperatures."}]},
{id:"w08",scene:"sensor",cat:"work",title:"8. センサー・信号",items:[{en:"The sensor isn't detecting the position correctly.",variants:[{q:"Is the sensor aligned correctly?",r:"It looks slightly out of alignment."},{q:"Does the signal change at the right position?",r:"No, the signal changes too early."}],alt:"The sensor isn't reading the position correctly.",ja:"センサーが位置を正しく検出していません。",a:"What's wrong with the sensor?",b:"The sensor isn't detecting the position correctly."},{en:"The signal changes too early.",ja:"信号の切り替わりが早すぎます。",a:"What did you observe?",b:"The signal changes too early."},{en:"Let's check the sensor alignment.",ja:"センサーの位置合わせを確認しましょう。",a:"What should we check?",b:"Let's check the sensor alignment."}]},
{id:"w09",scene:"electrical",cat:"work",title:"9. 電気・電源",items:[{en:"The breaker has tripped.",variants:[{q:"Should we reset it now?",r:"Not yet. Let’s find out why it tripped first."},{q:"Is the power isolated?",r:"Yes, the power has been isolated."}],ja:"ブレーカーが落ちています。",a:"Why is there no power?",b:"The breaker has tripped."},{en:"We need to check the voltage.",ja:"電圧を確認する必要があります。",a:"What should we measure?",b:"We need to check the voltage."},{en:"Don't touch the terminals until the power is isolated.",ja:"電源を遮断するまで端子に触れないでください。",a:"Can I check the terminals now?",b:"Don't touch the terminals until the power is isolated."}]},
{id:"w10",scene:"repair",cat:"work",title:"10. 修理後の確認",items:[{en:"The repair is complete.",variants:[{q:"Have you tested the machine yet?",r:"Yes, we ran a test after the repair."},{q:"Is everything operating normally now?",r:"Yes, everything looks normal now."}],alt:"We've finished the repair.",ja:"修理は完了しました。",a:"Is the repair finished?",b:"Yes. The repair is complete."},{en:"Let's run the machine and check it again.",ja:"機械を動かしてもう一度確認しましょう。",a:"What should we do now?",b:"Let's run the machine and check it again."},{en:"Everything looks normal now.",ja:"現在はすべて正常に見えます。",a:"How does it look now?",b:"Everything looks normal now."}]},
{id:"w11",scene:"history",cat:"work",title:"11. 故障履歴",items:[{en:"This problem happened once before.",variants:[{q:"When did it happen last time?",r:"It happened about a year ago."},{q:"What did we replace last time?",r:"We replaced the same part."}],ja:"この問題は以前にも一度発生しました。",a:"Has this happened before?",b:"Yes. This problem happened once before."},{en:"The same part was replaced last year.",ja:"同じ部品を去年交換しました。",a:"Was this part replaced before?",b:"The same part was replaced last year."},{en:"Let's check the maintenance record.",alt:"Let's look at the maintenance history.",ja:"保全記録を確認しましょう。",a:"How can we find out?",b:"Let's check the maintenance record."}]},
{id:"w12",scene:"diagnosis",cat:"work",title:"12. 原因切り分け",items:[{en:"Let's rule out the electrical side first.",ja:"まず電気系統を原因候補から切り分けましょう。",a:"Where should we start?",b:"Let's rule out the electrical side first."},{en:"If the pressure is stable, the valve may not be the cause.",ja:"圧力が安定しているなら、バルブが原因ではないかもしれません。",a:"Could the valve be the cause?",b:"If the pressure is stable, the valve may not be the cause."},{en:"We need more data before replacing the part.",variants:[{q:"What data do we still need?",r:"We need pressure and temperature data."},{q:"What should we rule out first?",r:"Let’s rule out the electrical side first."}],alt:"We need more information before we replace the part.",ja:"部品を交換する前に、さらにデータが必要です。",a:"Should we replace it now?",b:"We need more data before replacing the part."}]},
{id:"a03",cat:"advanced",title:"3. 仮説を説明する",items:[{en:"One possibility is that the signal is being interrupted.",ja:"一つの可能性は、信号が途切れていることです。",a:"What could explain this?",b:"One possibility is that the signal is being interrupted."},{en:"That would explain why the problem is intermittent.",ja:"それなら問題が断続的に起きる理由を説明できます。",a:"Does that fit what we're seeing?",b:"Yes. That would explain why the problem is intermittent."},{en:"We should test that hypothesis before making any changes.",ja:"変更する前に、その仮説を検証すべきです。",a:"Should we change the setting?",b:"Not yet. We should test that hypothesis before making any changes."}]},
{id:"a04",cat:"advanced",title:"4. 条件付きで提案する",items:[{en:"If the temperature rises again, we should stop the machine.",ja:"再び温度が上がったら、機械を停止すべきです。",a:"When should we stop it?",b:"If the temperature rises again, we should stop the machine."},{en:"As long as the pressure remains stable, we can continue the test.",ja:"圧力が安定している限り、試験を続けられます。",a:"Can we keep testing?",b:"As long as the pressure remains stable, we can continue the test."},{en:"I'd rather wait until we have enough data.",ja:"十分なデータが揃うまで待ちたいです。",a:"Should we decide now?",b:"I'd rather wait until we have enough data."}]},
{id:"a05",cat:"advanced",title:"5. 誤解を修正する",items:[{en:"That's not quite what I meant.",ja:"私が言いたかったのは少し違います。",a:"So you want to replace it?",b:"That's not quite what I meant."},{en:"What I'm saying is that we need to verify the cause first.",ja:"私が言いたいのは、まず原因を確認する必要があるということです。",a:"Then what do you mean?",b:"What I'm saying is that we need to verify the cause first."},{en:"Sorry, I should have explained that more clearly.",ja:"すみません、もっと分かりやすく説明すべきでした。",a:"I misunderstood you.",b:"Sorry, I should have explained that more clearly."}]},
{id:"a06",cat:"advanced",title:"6. メリットとリスク",items:[{en:"The advantage is that it reduces downtime.",ja:"利点は停止時間を減らせることです。",a:"What's the advantage?",b:"The advantage is that it reduces downtime."},{en:"The downside is that it requires more frequent inspections.",ja:"欠点は点検頻度を増やす必要があることです。",a:"Is there a downside?",b:"The downside is that it requires more frequent inspections."},{en:"We need to balance cost, safety, and reliability.",ja:"コスト、安全性、信頼性のバランスを取る必要があります。",a:"What should we consider?",b:"We need to balance cost, safety, and reliability."}]},
{id:"m03",cat:"master",title:"3. 即座に整理して返す",items:[{en:"There are two separate issues here.",ja:"ここには二つの別々の問題があります。",a:"What's your assessment?",b:"There are two separate issues here."},{en:"The immediate issue is the leak, while the underlying cause is still unclear.",ja:"差し迫った問題は漏れですが、根本原因はまだ不明です。",a:"What do we know so far?",b:"The immediate issue is the leak, while the underlying cause is still unclear."},{en:"Let's deal with the safety risk first and investigate the cause afterward.",ja:"まず安全上のリスクに対処し、その後で原因を調べましょう。",a:"What should we prioritize?",b:"Let's deal with the safety risk first and investigate the cause afterward."}]},
{id:"m04",cat:"master",title:"4. 反対意見に対応する",items:[{en:"I understand your concern, and I think we can address it.",ja:"懸念は理解しています。それに対応する方法があると思います。",a:"I'm worried this is going to take too long.",b:"I understand your concern, and I think we can address it."},{en:"That's a fair point, but the risk of restarting now is higher.",alt:"I see your point, but restarting now carries more risk.",ja:"もっともな指摘ですが、今再起動するリスクのほうが高いです。",a:"We cannot wait all day.",b:"That's a fair point, but the risk of restarting now is higher."},{en:"Could we agree to run one more test before deciding?",ja:"決める前に、もう一度だけ試験することで合意できませんか？",a:"What do you suggest?",b:"Could we agree to run one more test before deciding?"}]},
{id:"m05",cat:"master",title:"5. 不確実性を伝える",items:[{en:"I can't say for certain yet, but the data points in that direction.",ja:"まだ断定はできませんが、データはその方向を示しています。",a:"Are you sure that's the cause?",b:"I can't say for certain yet, but the data points in that direction."},{en:"Based on what we've seen so far, that's the most likely explanation.",ja:"これまで確認した内容からすると、それが最も可能性の高い説明です。",a:"What's your best guess?",b:"Based on what we've seen so far, that's the most likely explanation."},{en:"We should keep the other possibilities open.",ja:"ほかの可能性も残しておくべきです。",a:"Can we rule everything else out?",b:"No. We should keep the other possibilities open."}]},
{id:"m06",cat:"master",title:"6. 基本の交渉と合意",items:[{en:"I can agree to that if we add one more safety check.",ja:"安全確認をもう一つ追加するなら、それに同意できます。",a:"Can we proceed with this plan?",b:"I can agree to that if we add one more safety check."},{en:"That sounds like a reasonable compromise.",ja:"それなら妥当な妥協案だと思います。",a:"How about splitting the work?",b:"That sounds like a reasonable compromise."},{en:"Let's confirm exactly who will do what.",ja:"それぞれが何をするか正確に確認しましょう。",a:"Are we agreed?",b:"Yes. Let's confirm exactly who will do what."}]},
{id:"i09",cat:"intermediate",title:"9. 許可・確認",items:[{en:"Is it okay if I use this?",ja:"これを使ってもいいですか？",a:"Do you need this?",b:"Yes. Is it okay if I use this?"},{en:"Let me make sure I understood you correctly.",ja:"正しく理解できたか確認させてください。",a:"Do you understand?",b:"Let me make sure I understood you correctly."},{en:"So, you mean we should wait until tomorrow?",ja:"つまり明日まで待つということですか？",a:"Let's wait before we decide.",b:"So, you mean we should wait until tomorrow?"}]},
{id:"i10",cat:"intermediate",title:"10. 状況を詳しく説明",items:[{en:"It was working fine this morning.",ja:"今朝は正常に動いていました。",a:"Was there a problem earlier?",b:"No. It was working fine this morning."},{en:"The problem started after lunch.",ja:"問題は昼食後に始まりました。",a:"When did it start?",b:"The problem started after lunch."},{en:"It happens only when I use this function.",ja:"この機能を使うときだけ発生します。",a:"Does it happen all the time?",b:"No. It happens only when I use this function."}]},
{id:"i11",cat:"intermediate",title:"11. 提案・代案",items:[{en:"Why don't we try a different way?",ja:"別の方法を試してみませんか？",a:"This isn't working.",b:"Why don't we try a different way?"},{en:"We could do it tomorrow instead.",ja:"代わりに明日やることもできます。",a:"We don't have enough time today.",b:"We could do it tomorrow instead."},{en:"Another option is to ask for help.",ja:"別の選択肢は助けを求めることです。",a:"What else can we do?",b:"Another option is to ask for help."}]},
{id:"i12",cat:"intermediate",title:"12. 結果・変化",items:[{en:"It works much better now.",ja:"今はかなり良く動きます。",a:"How is it now?",b:"It works much better now."},{en:"Nothing changed after I restarted it.",ja:"再起動しても何も変わりませんでした。",a:"Did restarting help?",b:"No. Nothing changed after I restarted it."},{en:"The situation is gradually improving.",ja:"状況は徐々に改善しています。",a:"Is it getting better?",b:"Yes. The situation is gradually improving."}]},
{id:"d09",cat:"daily",title:"9. 電話・メッセージの応用",items:[{en:"I'll call you back later.",ja:"あとでかけ直します。",a:"Can you talk now?",b:"Not right now. I'll call you back later."},{en:"I sent you the details a few minutes ago.",ja:"今メッセージを送りました。",a:"Did you send it?",b:"Yes. I just sent you a message."},{en:"Sorry, I could not answer earlier.",ja:"すみません、電話に出られませんでした。",a:"I called you earlier.",b:"Sorry, I missed your call."}]},
{id:"d10",cat:"daily",title:"10. 天気・服装",items:[{en:"It looks like rain, so I will take an umbrella.",ja:"雨が降りそうです。",a:"How's the weather?",b:"It looks like it's going to rain."},{en:"It's colder than I expected.",ja:"思ったより寒いです。",a:"Is it cold outside?",b:"Yes. It's colder than I expected."},{en:"You might want to bring a jacket.",ja:"上着を持っていったほうがいいかもしれません。",a:"Do I need anything?",b:"You might want to bring a jacket."}]},
{id:"d11",cat:"daily",title:"11. 外食・カフェ",items:[{en:"Can we get a table for two?",ja:"2人席をお願いできますか？",a:"How many people?",b:"Can we get a table for two?"},{en:"I'll have the same, please.",ja:"私も同じものをお願いします。",a:"What would you like?",b:"I'll have the same, please."},{en:"Could I get this to go?",ja:"これを持ち帰りにできますか？",a:"For here or to go?",b:"Could I get this to go?"}]},
{id:"d12",cat:"daily",title:"12. 困りごとを頼む",items:[{en:"Could you help me with this?",ja:"これを手伝ってもらえますか？",a:"Do you need a hand?",b:"Yes. Could you help me with this?"},{en:"I'm having trouble opening this.",ja:"これを開けるのに苦労しています。",a:"What's wrong?",b:"I'm having trouble opening this."},{en:"Thanks, that really helped.",ja:"ありがとう、本当に助かりました。",a:"Is that better now?",b:"Yes. Thanks, that really helped."}]},
{id:"t09",cat:"travel",title:"9. 空港で搭乗手続き",items:[{en:"I'd like to check in for my flight.",ja:"搭乗手続きをお願いします。",a:"May I see your passport?",b:"Sure. I'd like to check in for my flight."},{en:"Can I check this bag?",ja:"この荷物を預けられますか？",a:"Do you have any bags to check?",b:"Yes. Can I check this bag?"},{en:"Is the flight on time?",ja:"飛行機は定刻どおりですか？",a:"Do you have a question about your flight?",b:"Yes. Is the flight on time?"}]},
{id:"t10",cat:"travel",title:"10. 入国審査",items:[{en:"I'm here for sightseeing.",ja:"観光で来ました。",a:"What is the purpose of your visit?",b:"I'm here for sightseeing."},{en:"I'll be staying for five days.",ja:"5日間滞在します。",a:"How long will you be staying?",b:"I'll be staying for five days."},{en:"I'm staying at a hotel in the city.",ja:"市内のホテルに泊まります。",a:"Where are you staying?",b:"I'm staying at a hotel in the city."}]},
{id:"t11",cat:"travel",title:"11. タクシー・配車",items:[{en:"Could you take me to this address?",ja:"この住所までお願いします。",a:"Where would you like to go?",b:"Could you take me to this address?"},{en:"About how long will it take?",ja:"だいたいどのくらいかかりますか？",a:"Do you need to be there soon?",b:"Yes. About how long will it take?"},{en:"You can drop me off here.",ja:"ここで降ろしてください。",a:"Is this okay?",b:"Yes. You can drop me off here."}]},
{id:"t12",cat:"travel",title:"12. ホテルでの要望",items:[{en:"Could I get an extra towel?",ja:"タオルをもう1枚いただけますか？",a:"How can I help you?",b:"Could I get an extra towel?"},{en:"The air conditioner isn't working.",ja:"エアコンが動きません。",a:"Is there a problem with the room?",b:"Yes. The air conditioner isn't working."},{en:"Could someone take a look at it?",ja:"誰かに見てもらえますか？",a:"Would you like us to check it?",b:"Yes. Could someone take a look at it?"}]},
{id:"w13",cat:"work",title:"13. 仕事を依頼・引き受ける",items:[{en:"Could you take care of this today?",ja:"今日これを対応してもらえますか？",a:"What do you need me to do?",b:"Could you take care of this today?"},{en:"I'll handle it after lunch.",ja:"昼食後に対応します。",a:"When can you do it?",b:"I'll handle it after lunch."},{en:"Let me know when you're finished.",ja:"終わったら知らせてください。",a:"Anything else?",b:"Let me know when you're finished."}]},
{id:"w14",cat:"work",title:"14. 進捗を簡潔に報告する",items:[{en:"I'm about halfway done.",ja:"だいたい半分終わりました。",a:"How's it going?",b:"I'm about halfway done."},{en:"It's taking longer than expected.",ja:"予想より時間がかかっています。",a:"Will it be done soon?",b:"It's taking longer than expected."},{en:"I should be finished by three.",ja:"3時までには終わると思います。",a:"When will you finish?",b:"I should be finished by three."}]},
{id:"w15",cat:"work",title:"15. 打ち合わせで確認する",items:[{en:"Let's go over the main points first.",ja:"まず要点を確認しましょう。",a:"Where should we start?",b:"Let's go over the main points first."},{en:"I have one question about the schedule.",ja:"予定について1つ質問があります。",a:"Any questions?",b:"I have one question about the schedule."},{en:"Let's make sure we're all on the same page.",ja:"全員の認識が合っているか確認しましょう。",a:"Are we ready to move on?",b:"Let's make sure we're all on the same page."}]},
{id:"w16",cat:"work",title:"16. 作業前の安全確認",items:[{en:"Make sure the power is off before you start.",ja:"始める前に電源が切れていることを確認してください。",a:"Can I start now?",b:"Make sure the power is off before you start."},{en:"The area needs to be secured first.",ja:"まず周囲の安全を確保する必要があります。",a:"What's the first step?",b:"The area needs to be secured first."},{en:"Stop immediately if anything looks unsafe.",ja:"危険に見えることがあればすぐ停止してください。",a:"What should I do if I notice a problem?",b:"Stop immediately if anything looks unsafe."}]},
{id:"i13",cat:"intermediate",title:"13. 理由を2つ伝える",items:[{en:"I prefer this option because it is simpler and faster.",ja:"こちらのほうが簡単で速いので、この案がいいです。",a:"Why do you prefer this option?",b:"I prefer this option because it is simpler and faster.",variants:[{q:"What makes this option better?",r:"It is simpler to use and it saves time."},{q:"Is cost the main reason?",r:"No, simplicity and speed are more important here."}]},{en:"There are two reasons I think we should wait.",ja:"待ったほうがよいと思う理由が2つあります。",a:"Why should we wait?",b:"There are two reasons I think we should wait."},{en:"It is safer, and it also gives us more time to check.",ja:"より安全ですし、確認する時間も増えます。",a:"What are the benefits?",b:"It is safer, and it also gives us more time to check."}]},
{id:"i14",cat:"intermediate",title:"14. 相手の考えを確認",items:[{en:"What do you think about this idea?",ja:"この案についてどう思いますか？",a:"Do you have a suggestion?",b:"Yes, but first, what do you think about this idea?"},{en:"Do you see any problems with this plan?",ja:"この計画に何か問題があると思いますか？",a:"Are we ready to proceed?",b:"Do you see any problems with this plan?"},{en:"Does that make sense to you?",ja:"今の説明で意味は通じましたか？",a:"I think I understand.",b:"Good. Does that make sense to you?"}]},
{id:"i15",cat:"intermediate",title:"15. やわらかく反対する",items:[{en:"I am not sure that is the best option.",ja:"それが最善の選択かは少し疑問です。",a:"Should we choose this one?",b:"I am not sure that is the best option."},{en:"I see your point, but I have one concern.",ja:"言いたいことは分かりますが、1つ懸念があります。",a:"I think we should start now.",b:"I see your point, but I have one concern.",variants:[{q:"What are you concerned about?",r:"I am concerned about the safety risk."},{q:"Do you disagree completely?",r:"No. I agree with the idea, but I have one concern."}]},{en:"I agree with most of it, but I would change one thing.",ja:"大部分は賛成ですが、1点だけ変えたいです。",a:"Do you agree with the plan?",b:"I agree with most of it, but I would change one thing."}]},
{id:"i16",cat:"intermediate",title:"16. 条件をつける",items:[{en:"We can continue if the temperature stays stable.",ja:"温度が安定していれば続けられます。",a:"Can we continue?",b:"We can continue if the temperature stays stable.",variants:[{q:"What if the temperature rises?",r:"Then we should stop and check the system."},{q:"What condition are you watching?",r:"We are watching whether the temperature stays stable."}]},{en:"If we finish early, we can check it again.",ja:"早く終われば、もう一度確認できます。",a:"Can we check it again today?",b:"If we finish early, we can check it again."},{en:"As long as it is safe, I am okay with that plan.",ja:"安全である限り、その計画で大丈夫です。",a:"Are you okay with this plan?",b:"As long as it is safe, I am okay with that plan."}]},
{id:"i17",cat:"intermediate",title:"17. 要点をまとめる",items:[{en:"So, the main problem is the delay.",ja:"つまり、主な問題は遅れです。",a:"Can you summarize the problem?",b:"So, the main problem is the delay."},{en:"In short, we need more time and more information.",ja:"要するに、もっと時間と情報が必要です。",a:"What do we need?",b:"In short, we need more time and more information.",variants:[{q:"What information is missing?",r:"We still need the latest measurements."},{q:"Can we decide now?",r:"Not yet. We need more information first."}]},{en:"The key point is that we should not rush.",ja:"重要なのは、急ぐべきではないということです。",a:"What is the key point?",b:"The key point is that we should not rush."}]},
{id:"i18",cat:"intermediate",title:"18. 技術的な状況を短く説明する",items:[{en:"The machine stopped because the pressure dropped.",ja:"圧力が下がったため機械が停止しました。",a:"Why did the machine stop?",b:"The machine stopped because the pressure dropped."},{en:"We checked the sensor, but we have not found the cause yet.",ja:"センサーは確認しましたが、まだ原因は見つかっていません。",a:"What have you checked so far?",b:"We checked the sensor, but we have not found the cause yet.",variants:[{q:"What will you check next?",r:"Next, we will compare the signal and pressure data."},{q:"Have you ruled out the sensor?",r:"Not completely. We still need to verify the signal."}]},{en:"Our next step is to compare the readings.",ja:"次は測定値を比較します。",a:"What is the next step?",b:"Our next step is to compare the readings."}]},
{id:"d13",cat:"daily",title:"13. 予定を変更する",items:[{en:"Can we move it to tomorrow?",ja:"明日に変更できますか？",a:"Does today still work for you?",b:"Can we move it to tomorrow?"},{en:"Something came up this afternoon.",ja:"今日の午後に急な用事ができました。",a:"Why do you need to change the plan?",b:"Something came up this afternoon."},{en:"Tomorrow works better for me.",ja:"私には明日のほうが都合がいいです。",a:"How about tomorrow?",b:"Tomorrow works better for me."}]},
{id:"d14",cat:"daily",title:"14. 家族・知人について話す",items:[{en:"My mother lives nearby.",ja:"母は近くに住んでいます。",a:"Does your family live far away?",b:"My mother lives nearby."},{en:"I am going to visit my family this weekend.",ja:"今週末は家族に会いに行きます。",a:"What are you doing this weekend?",b:"I am going to visit my family this weekend."},{en:"We do not see each other very often.",ja:"私たちはあまり頻繁には会いません。",a:"Do you see each other often?",b:"No. We do not see each other very often."}]},
{id:"d15",cat:"daily",title:"15. 体調が悪い人への対応",items:[{en:"You should get some rest.",ja:"少し休んだほうがいいですよ。",a:"I am not feeling well.",b:"You should get some rest."},{en:"Do you need me to get anything for you?",ja:"何か取ってきましょうか？",a:"I have a headache.",b:"Do you need me to get anything for you?"},{en:"Let me know if you feel worse.",ja:"もっと具合が悪くなったら教えてください。",a:"I think I will be okay.",b:"Let me know if you feel worse."}]},
{id:"d16",cat:"daily",title:"16. 荷物・宅配",items:[{en:"A package arrived for you.",ja:"あなた宛ての荷物が届きました。",a:"Did anything arrive today?",b:"Yes. A package arrived for you."},{en:"Could you leave it by the door?",ja:"ドアのそばに置いてもらえますか？",a:"Where should I leave the package?",b:"Could you leave it by the door?"},{en:"I am waiting for a delivery.",ja:"配達を待っています。",a:"Are you expecting something?",b:"Yes. I am waiting for a delivery."}]},
{id:"d17",cat:"daily",title:"17. お礼・おわび",items:[{en:"Thanks for taking the time to help me.",ja:"時間を取って手伝ってくれてありがとう。",a:"Was that helpful?",b:"Yes. Thanks for taking the time to help me."},{en:"I am sorry for the trouble.",ja:"ご迷惑をおかけしてすみません。",a:"It took a while to fix.",b:"I am sorry for the trouble."},{en:"Do not worry about it.",ja:"気にしないでください。",a:"I am really sorry.",b:"Do not worry about it."}]},
{id:"t13",cat:"travel",title:"13. 予約を変更する",items:[{en:"I would like to change my reservation.",ja:"予約を変更したいです。",a:"How can I help you?",b:"I would like to change my reservation."},{en:"Is there anything available on Friday?",ja:"金曜日に空きはありますか？",a:"Which day would you prefer?",b:"Is there anything available on Friday?"},{en:"Could you confirm the new date for me?",ja:"新しい日付を確認してもらえますか？",a:"The change is complete.",b:"Could you confirm the new date for me?"}]},
{id:"t14",cat:"travel",title:"14. 荷物をなくした",items:[{en:"I cannot find my bag.",ja:"バッグが見つかりません。",a:"What seems to be the problem?",b:"I cannot find my bag."},{en:"I last saw it near the gate.",ja:"最後に見たのは搭乗口の近くです。",a:"Where did you last see it?",b:"I last saw it near the gate."},{en:"Where is the lost and found?",ja:"遺失物取扱所はどこですか？",a:"Do you need help finding it?",b:"Yes. Where is the lost and found?"}]},
{id:"t15",cat:"travel",title:"15. 道に迷った",items:[{en:"I think I am lost.",ja:"道に迷ったようです。",a:"Do you need help?",b:"Yes. I think I am lost."},{en:"Am I going in the right direction?",ja:"この方向で合っていますか？",a:"Where are you trying to go?",b:"Am I going in the right direction?"},{en:"Could you show me on the map?",ja:"地図で教えてもらえますか？",a:"It is a little difficult to explain.",b:"Could you show me on the map?"}]},
{id:"t16",cat:"travel",title:"16. 支払いトラブル",items:[{en:"My card is not working.",ja:"カードが使えません。",a:"The payment did not go through.",b:"My card is not working."},{en:"Can I pay another way?",ja:"別の方法で支払えますか？",a:"Would you like to try again?",b:"Can I pay another way?"},{en:"I think I was charged twice.",ja:"二重に請求されたと思います。",a:"What is the problem with the payment?",b:"I think I was charged twice."}]},
{id:"t17",cat:"travel",title:"17. 遅延・欠航",items:[{en:"The departure has been pushed back by an hour.",ja:"飛行機が遅れています。",a:"What happened to your flight?",b:"My flight has been delayed."},{en:"When is the new departure time?",ja:"新しい出発時刻はいつですか？",a:"Do you need the updated schedule?",b:"Yes. When is the new departure time?"},{en:"What are my options if the flight is canceled?",ja:"欠航した場合、どんな選択肢がありますか？",a:"The flight may be canceled.",b:"What are my options if the flight is canceled?"}]},
{id:"w17",cat:"work",title:"17. 測定値を比較して伝える",items:[{en:"The temperature is higher than yesterday.",ja:"温度は昨日より高いです。",a:"How does today's reading compare?",b:"The temperature is higher than yesterday."},{en:"The pressure is within the normal range.",ja:"圧力は正常範囲内です。",a:"Is the pressure okay?",b:"Yes. The pressure is within the normal range."},{en:"The readings are stable so far.",ja:"今のところ測定値は安定しています。",a:"Are the readings changing?",b:"No. The readings are stable so far."}]},
{id:"w18",cat:"work",title:"18. 部品交換を相談する",items:[{en:"This part needs to be replaced.",ja:"この部品は交換が必要です。",a:"Can we keep using it?",b:"No. This part needs to be replaced."},{en:"Do we have a spare in stock?",ja:"予備品の在庫はありますか？",a:"What do we need before the repair?",b:"Do we have a spare in stock?"},{en:"Let's compare the old and new parts.",ja:"古い部品と新しい部品を比較しましょう。",a:"What should we do before installing it?",b:"Let's compare the old and new parts."}]},
{id:"w19",cat:"work",title:"19. 原因と再発防止を話す",items:[{en:"We need to prevent this from happening again.",ja:"これが再発しないようにする必要があります。",a:"The machine is running again. Are we done?",b:"Not yet. We need to prevent this from happening again."},{en:"Let's review what caused the failure.",ja:"故障の原因を振り返りましょう。",a:"Where should we start?",b:"Let's review what caused the failure."},{en:"We should add this point to the inspection checklist.",ja:"この項目を点検表に追加すべきです。",a:"How can we catch it earlier next time?",b:"We should add this point to the inspection checklist."}]},
{id:"w20",cat:"work",title:"20. 未解決事項まで引き継ぐ",items:[{en:"The machine is running, but please keep an eye on the pressure.",ja:"機械は稼働していますが、圧力を注意して見てください。",a:"Is there anything I should watch?",b:"The machine is running, but please keep an eye on the pressure."},{en:"The problem has not been fully resolved yet.",ja:"問題はまだ完全には解決していません。",a:"Is everything fixed?",b:"No. The problem has not been fully resolved yet."},{en:"If the alarm comes back, stop the machine and call me.",ja:"警報が再発したら機械を止めて連絡してください。",a:"What should I do if the alarm returns?",b:"If the alarm comes back, stop the machine and call me."}]},
{id:"w21",cat:"work",title:"21. 経験者へ切り分けを相談する",items:[{en:"Can I get your opinion on this?",ja:"これについて意見をもらえますか？",a:"Do you need something?",b:"Can I get your opinion on this?"},{en:"I have checked the obvious causes, but I am still not sure.",ja:"明らかな原因は確認しましたが、まだ判断できません。",a:"What have you found?",b:"I have checked the obvious causes, but I am still not sure."},{en:"What would you check next?",ja:"次に何を確認しますか？",a:"Do you want a suggestion?",b:"Yes. What would you check next?"}]},
{id:"a11",cat:"advanced",title:"7. 根拠を添えて意見を述べる",items:[{en:"I think we should wait because we still do not know the root cause.",ja:"まだ根本原因が分からないので、待つべきだと思います。",a:"Should we restart now?",b:"I think we should wait because we still do not know the root cause."},{en:"Based on the data we have, replacing the part now would be premature.",ja:"現在のデータからすると、今その部品を交換するのは時期尚早です。",a:"Should we replace it?",b:"Based on the data we have, replacing the part now would be premature."},{en:"My main concern is that the same failure could happen again.",ja:"一番の懸念は、同じ故障が再発する可能性があることです。",a:"What concerns you most?",b:"My main concern is that the same failure could happen again."}]},
{id:"a12",cat:"advanced",title:"8. 比較して選択する",items:[{en:"The first option is faster, but the second one is safer.",ja:"1つ目の案は速いですが、2つ目のほうが安全です。",a:"How do the two options compare?",b:"The first option is faster, but the second one is safer."},{en:"This approach takes longer, but it gives us more reliable information.",ja:"この方法は時間がかかりますが、より信頼できる情報が得られます。",a:"Why use this approach?",b:"This approach takes longer, but it gives us more reliable information."},{en:"If safety is the priority, I would choose the second option.",ja:"安全を優先するなら、私は2つ目を選びます。",a:"Which would you choose?",b:"If safety is the priority, I would choose the second option."}]},
{id:"a13",cat:"advanced",title:"9. 反対意見に応じる",items:[{en:"I understand the concern, but I do not think waiting will solve the problem.",ja:"懸念は分かりますが、待つだけでは問題は解決しないと思います。",a:"Would it be better to wait?",b:"I understand the concern, but I do not think waiting will solve the problem."},{en:"That is possible, although the measurements suggest something else.",ja:"その可能性はありますが、測定値は別のことを示しています。",a:"Could the sensor be the cause?",b:"That is possible, although the measurements suggest something else."},{en:"You may be right, so let us verify it before we decide.",ja:"その可能性もあるので、決める前に確認しましょう。",a:"I think the valve is the problem.",b:"You may be right, so let us verify it before we decide."}]},
{id:"a14",cat:"advanced",title:"10. 条件を調整する",items:[{en:"I can agree to that as long as we check the pressure first.",ja:"先に圧力を確認するなら、その案に賛成できます。",a:"Can we restart the machine?",b:"I can agree to that as long as we check the pressure first."},{en:"We can shorten the test, provided that the readings remain stable.",ja:"測定値が安定していることを条件に、試験時間を短縮できます。",a:"Can we make the test shorter?",b:"We can shorten the test, provided that the readings remain stable."},{en:"If we cannot confirm the cause, we should postpone the restart.",ja:"原因を確認できなければ、再起動を延期すべきです。",a:"What if we still cannot find the cause?",b:"If we cannot confirm the cause, we should postpone the restart."}]},
{id:"a07",cat:"advanced",title:"11. 原因を段階的に説明する",items:[{en:"The pressure dropped first, then the alarm came on, and the machine stopped.",ja:"まず圧力が低下し、その後警報が出て機械が停止しました。",a:"What happened?",b:"The pressure dropped first, then the alarm came on, and the machine stopped."},{en:"We ruled out the sensor, so now we are checking the valve and the piping.",ja:"センサーは除外できたので、現在はバルブと配管を確認しています。",a:"What are you checking now?",b:"We ruled out the sensor, so now we are checking the valve and the piping."},{en:"The evidence points to a leak, but we have not confirmed the exact location yet.",ja:"状況から漏れが疑われますが、正確な箇所はまだ確認できていません。",a:"Do you know the cause?",b:"The evidence points to a leak, but we have not confirmed the exact location yet."}]},
{id:"a08",cat:"advanced",title:"12. 不確実さを正確に伝える",items:[{en:"We cannot rule it out yet.",ja:"まだその可能性を除外できません。",a:"Can we rule out an electrical problem?",b:"We cannot rule it out yet."},{en:"It appears to be related, but we need more data to be sure.",ja:"関連しているようですが、確定にはさらにデータが必要です。",a:"Is this related to the temperature rise?",b:"It appears to be related, but we need more data to be sure."},{en:"At this point, that is our most likely explanation.",ja:"現時点では、それが最も可能性の高い説明です。",a:"What do you think caused it?",b:"At this point, that is our most likely explanation."}]},
{id:"a09",cat:"advanced",title:"13. 長い説明を要約する",items:[{en:"To sum up, the machine is stable now, but the root cause is still unclear.",ja:"まとめると、機械は現在安定していますが、根本原因はまだ不明です。",a:"Can you summarize the situation?",b:"To sum up, the machine is stable now, but the root cause is still unclear."},{en:"The short version is that we can operate it, but we need to keep monitoring it.",ja:"簡単に言うと、運転はできますが監視を続ける必要があります。",a:"What is the short version?",b:"The short version is that we can operate it, but we need to keep monitoring it."},{en:"The main takeaway is that replacing the part alone may not solve the problem.",ja:"要点は、その部品を交換するだけでは問題が解決しない可能性があることです。",a:"What is the main takeaway?",b:"The main takeaway is that replacing the part alone may not solve the problem."}]},
{id:"a10",cat:"advanced",title:"14. 説明を言い換える",items:[{en:"Let me explain that in a simpler way.",ja:"もっと簡単に説明します。",a:"I am not sure I understand.",b:"Let me explain that in a simpler way."},{en:"What I mean is that the problem may be somewhere else.",ja:"つまり、問題は別の場所にあるかもしれないということです。",a:"Do you mean this part is fine?",b:"What I mean is that the problem may be somewhere else."},{en:"Another way to put it is that we are treating the symptom, not the cause.",ja:"別の言い方をすると、原因ではなく症状に対処しているということです。",a:"Why is replacing the part not enough?",b:"Another way to put it is that we are treating the symptom, not the cause."}]},
{id:"m09",cat:"master",title:"7. 即興で説明を組み替える",items:[{en:"Let me put that another way so it is clearer.",ja:"より分かりやすいように別の言い方をします。",a:"Could you explain that differently?",b:"Let me put that another way so it is clearer."},{en:"In practical terms, we need to stop and inspect it before continuing.",ja:"実際の対応としては、続ける前に停止して点検する必要があります。",a:"What does that mean in practice?",b:"In practical terms, we need to stop and inspect it before continuing."},{en:"To say it more simply, we do not have enough evidence yet.",ja:"もっと簡単に言うと、まだ十分な根拠がありません。",a:"Can you simplify that?",b:"To say it more simply, we do not have enough evidence yet."}]},
{id:"m10",cat:"master",title:"8. 曖昧な質問に対応する",items:[{en:"It depends on what you mean by normal.",ja:"「正常」の意味によります。",a:"Is this normal?",b:"It depends on what you mean by normal."},{en:"Could you be a little more specific about what changed?",ja:"何が変わったのか、もう少し具体的に教えてもらえますか？",a:"Something seems different.",b:"Could you be a little more specific about what changed?"},{en:"There are several possibilities, so I would like to narrow it down first.",ja:"いくつか可能性があるので、まず絞り込みたいです。",a:"What is causing this?",b:"There are several possibilities, so I would like to narrow it down first."}]},
{id:"m11",cat:"master",title:"9. 条件を提示して交渉する",items:[{en:"If you can give us another hour, we can complete the inspection safely.",ja:"あと1時間いただければ、安全に点検を完了できます。",a:"We need the machine back now.",b:"If you can give us another hour, we can complete the inspection safely."},{en:"I can accept that compromise if we continue monitoring the pressure.",ja:"圧力監視を続けるなら、その妥協案を受け入れられます。",a:"Can we run it at reduced speed?",b:"I can accept that compromise if we continue monitoring the pressure."},{en:"That sounds reasonable. Let's proceed on that basis.",ja:"妥当だと思います。その条件で進めましょう。",a:"Can we agree on this plan?",b:"That sounds reasonable. Let's proceed on that basis."}]},
{id:"m12",cat:"master",title:"10. 相手に合わせて説明する",items:[{en:"For someone who does not work with this machine, the easiest way to explain it is this.",ja:"この機械を扱わない人向けなら、こう説明するのが一番分かりやすいです。",a:"Can you explain it to a non-specialist?",b:"For someone who does not work with this machine, the easiest way to explain it is this."},{en:"Technically, the issue is more complicated, but the immediate risk is simple.",ja:"技術的にはもっと複雑ですが、差し迫ったリスクは単純です。",a:"Do I need all the technical details?",b:"Technically, the issue is more complicated, but the immediate risk is simple."},{en:"The important thing for the next shift is what to watch and when to stop.",ja:"次のシフトに重要なのは、何を監視し、いつ停止するかです。",a:"What should I tell the next shift?",b:"The important thing for the next shift is what to watch and when to stop."}]},
{id:"m07",cat:"master",title:"11. 情報不足でも判断を進める",items:[{en:"We do not have all the information, but we have enough to choose the safest next step.",ja:"情報は全部そろっていませんが、最も安全な次の一手を選ぶには十分です。",a:"Can we make a decision yet?",b:"We do not have all the information, but we have enough to choose the safest next step."},{en:"Rather than guessing the cause, I would focus on what we can verify now.",ja:"原因を推測するより、今確認できることに集中します。",a:"What do you think the cause is?",b:"Rather than guessing the cause, I would focus on what we can verify now."},{en:"The uncertainty itself is a reason to proceed cautiously.",ja:"不確実であること自体が、慎重に進める理由です。",a:"Why are you being so cautious?",b:"The uncertainty itself is a reason to proceed cautiously."}]},
{id:"m08",cat:"master",title:"12. 複数の立場を整理する",items:[{en:"Operations wants a quick restart, while maintenance wants more time to investigate.",ja:"生産側は早期再開を望み、保全側は調査時間を求めています。",a:"Why is it difficult to agree?",b:"Operations wants a quick restart, while maintenance wants more time to investigate."},{en:"Both sides have a valid concern, so we need a plan that addresses safety and downtime.",ja:"双方に妥当な懸念があるので、安全と停止時間の両方に対応する計画が必要です。",a:"Whose concern is more important?",b:"Both sides have a valid concern, so we need a plan that addresses safety and downtime."},{en:"The best solution may be a temporary restart with clear stop conditions.",ja:"最善策は、明確な停止条件を設けた一時的な再開かもしれません。",a:"Is there a compromise?",b:"The best solution may be a temporary restart with clear stop conditions."}]},
{id:"d18",cat:"daily",title:"18. 趣味を詳しく話す",items:[{en:"I usually go for a ride on weekends.",ja:"週末はよくバイクで出かけます。",a:"What do you do on weekends?",b:"I usually go for a ride on weekends."},{en:"I started doing it a few years ago.",ja:"数年前に始めました。",a:"How long have you been doing that?",b:"I started doing it a few years ago."},{en:"It helps me relax after a busy week.",ja:"忙しい一週間のあとに気分転換になります。",a:"Why do you enjoy it?",b:"It helps me relax after a busy week."}]},
{id:"d19",cat:"daily",title:"19. 最近の出来事を話す",items:[{en:"I tried a new restaurant yesterday.",ja:"昨日、新しいレストランに行ってみました。",a:"Did you do anything interesting yesterday?",b:"I tried a new restaurant yesterday."},{en:"It was better than I expected.",ja:"思っていたより良かったです。",a:"How was it?",b:"It was better than I expected."},{en:"I would definitely go there again.",ja:"ぜひまた行きたいです。",a:"Would you go back?",b:"I would definitely go there again."}]},
{id:"d20",cat:"daily",title:"20. 相手に詳しく聞く",items:[{en:"What was the best part?",ja:"一番良かったのは何ですか？",a:"I had a great weekend.",b:"What was the best part?"},{en:"How did you find that place?",ja:"その場所をどうやって見つけたのですか？",a:"I found a really nice cafe.",b:"How did you find that place?"},{en:"Would you recommend it?",ja:"おすすめしますか？",a:"The hotel was pretty good.",b:"Would you recommend it?"}]},
{id:"t18",cat:"travel",title:"18. 観光案内を聞く",items:[{en:"What is worth seeing around here?",ja:"この辺りで見る価値がある場所はどこですか？",a:"Are you looking for somewhere to visit?",b:"Yes. What is worth seeing around here?"},{en:"Is it within walking distance?",ja:"歩いて行ける距離ですか？",a:"The castle is nearby.",b:"Is it within walking distance?"},{en:"How much time should I allow for the visit?",ja:"見学にはどのくらい時間を見ておけばいいですか？",a:"Are you planning to visit the museum?",b:"Yes. How much time should I allow for the visit?"}]},
{id:"t19",cat:"travel",title:"19. 現地のおすすめを聞く",items:[{en:"Where do locals usually eat?",ja:"地元の人は普段どこで食べますか？",a:"Are you looking for a restaurant?",b:"Yes. Where do locals usually eat?"},{en:"Is there a local dish I should try?",ja:"食べておくべき郷土料理はありますか？",a:"Would you like to try something local?",b:"Yes. Is there a local dish I should try?"},{en:"I would prefer somewhere that is not too crowded.",ja:"あまり混んでいない所がいいです。",a:"What kind of place are you looking for?",b:"I would prefer somewhere that is not too crowded."}]},
{id:"t20",cat:"travel",title:"20. 予定を組み直す",items:[{en:"We may need to change our plans because of the weather.",ja:"天気のため予定を変更する必要があるかもしれません。",a:"Are we still going today?",b:"We may need to change our plans because of the weather."},{en:"What can we do indoors instead?",ja:"代わりに屋内で何ができますか？",a:"It is going to rain all afternoon.",b:"What can we do indoors instead?"},{en:"Let us save that for tomorrow if the weather improves.",ja:"天気が良くなれば、それは明日にしましょう。",a:"Should we cancel it?",b:"Let us save that for tomorrow if the weather improves."}]},
{id:"a15",cat:"advanced",title:"15. 優先順位を説明する",items:[{en:"Safety comes first, even if it means a longer delay.",ja:"遅れが長くなっても、安全が最優先です。",a:"What matters most right now?",b:"Safety comes first, even if it means a longer delay."},{en:"Our first priority is to prevent further damage.",ja:"最優先は、さらなる損傷を防ぐことです。",a:"What should we focus on first?",b:"Our first priority is to prevent further damage."},{en:"Once that is under control, we can focus on restoring operation.",ja:"それを抑えたら、運転復旧に集中できます。",a:"What comes next?",b:"Once that is under control, we can focus on restoring operation."}]},
{id:"a16",cat:"advanced",title:"16. 仮説を比較する",items:[{en:"The leak theory fits the pressure data better than the sensor theory.",ja:"漏れの仮説のほうが、センサーの仮説より圧力データに合います。",a:"Which explanation fits the data better?",b:"The leak theory fits the pressure data better than the sensor theory."},{en:"Both are possible, but only one explains the temperature change.",ja:"どちらも可能ですが、温度変化を説明できるのは一方だけです。",a:"Could either one be the cause?",b:"Both are possible, but only one explains the temperature change."},{en:"We need a test that can distinguish between the two possibilities.",ja:"2つの可能性を区別できる試験が必要です。",a:"How can we tell which one is right?",b:"We need a test that can distinguish between the two possibilities."}]},
{id:"a17",cat:"advanced",title:"17. 判断の限界を伝える",items:[{en:"The data is useful, but it is not enough to draw a firm conclusion.",ja:"データは有用ですが、確かな結論を出すには不十分です。",a:"Can we conclude that this is the cause?",b:"The data is useful, but it is not enough to draw a firm conclusion."},{en:"I would treat this as a working hypothesis for now.",ja:"今のところは作業仮説として扱います。",a:"Are you certain about the cause?",b:"I would treat this as a working hypothesis for now."},{en:"We should update our conclusion if new evidence points elsewhere.",ja:"新しい証拠が別の方向を示せば、結論を見直すべきです。",a:"What if we find new evidence?",b:"We should update our conclusion if new evidence points elsewhere."}]},
{id:"m13",cat:"master",title:"13. 想定外の質問へ返す",items:[{en:"That is a good question. I would need to check the data before answering.",ja:"良い質問です。答える前にデータを確認する必要があります。",a:"Could this fail again tomorrow?",b:"That is a good question. I would need to check the data before answering."},{en:"I do not want to guess, so let me verify that first.",ja:"推測では答えたくないので、まず確認させてください。",a:"Exactly how long will the repair last?",b:"I do not want to guess, so let me verify that first."},{en:"I can give you a preliminary answer, but not a final one yet.",ja:"暫定的な回答はできますが、まだ最終回答ではありません。",a:"What is your conclusion?",b:"I can give you a preliminary answer, but not a final one yet."}]},
{id:"m14",cat:"master",title:"14. 長い話から核心を抜く",items:[{en:"The key issue is not the alarm itself but what caused it.",ja:"核心は警報そのものではなく、何が警報を引き起こしたかです。",a:"What is the real issue here?",b:"The key issue is not the alarm itself but what caused it."},{en:"Most of those details are secondary; the pressure drop is the important clue.",ja:"その多くは二次的な情報で、重要な手掛かりは圧力低下です。",a:"Which detail matters most?",b:"Most of those details are secondary; the pressure drop is the important clue."},{en:"If I had to reduce it to one point, I would focus on the timing.",ja:"1点に絞るなら、発生タイミングに注目します。",a:"What would you focus on?",b:"If I had to reduce it to one point, I would focus on the timing."}]},
{id:"m15",cat:"master",title:"15. 相手の前提を確認する",items:[{en:"Before I answer, can I check what you are assuming?",ja:"答える前に、どのような前提で考えているか確認してもいいですか？",a:"Why did the valve fail?",b:"Before I answer, can I check what you are assuming?"},{en:"Are we assuming the sensor reading is accurate?",ja:"センサーの測定値が正確だという前提ですか？",a:"The pressure must be low.",b:"Are we assuming the sensor reading is accurate?"},{en:"If that assumption is wrong, our conclusion could change completely.",ja:"その前提が間違っていれば、結論は大きく変わる可能性があります。",a:"Why does the assumption matter?",b:"If that assumption is wrong, our conclusion could change completely."}]},
{id:"i19",cat:"intermediate",title:"19. 過去の事例と今回を比べる",items:[{en:"I have dealt with a similar problem before.",ja:"以前、似た問題に対応したことがあります。",a:"Have you seen this before?",b:"I have dealt with a similar problem before."},{en:"Last time, the cause was a loose connection.",ja:"前回は接続の緩みが原因でした。",a:"What caused it last time?",b:"Last time, the cause was a loose connection."},{en:"This time, however, the symptoms are slightly different.",ja:"ただし今回は症状が少し違います。",a:"Is it exactly the same this time?",b:"No. This time, however, the symptoms are slightly different."}]},
{id:"i20",cat:"intermediate",title:"20. 条件を含めて手順を説明する",items:[{en:"First, make sure the machine is stopped.",ja:"まず機械が停止していることを確認してください。",a:"What should I do first?",b:"First, make sure the machine is stopped."},{en:"Next, check whether the pressure has dropped.",ja:"次に圧力が低下しているか確認してください。",a:"What comes next?",b:"Next, check whether the pressure has dropped."},{en:"If everything looks normal, restart it carefully.",ja:"すべて正常なら、慎重に再起動してください。",a:"What if everything looks normal?",b:"If everything looks normal, restart it carefully."}]},
{id:"i21",cat:"intermediate",title:"21. 根拠をたずねて考えを深める",items:[{en:"What makes you think that is the cause?",ja:"なぜそれが原因だと思うのですか？",a:"I think the valve is the problem.",b:"What makes you think that is the cause?"},{en:"Is there any evidence for that?",ja:"それを裏付ける根拠はありますか？",a:"The sensor may be failing.",b:"Is there any evidence for that?"},{en:"Could there be another explanation?",ja:"別の説明も考えられませんか？",a:"This must be the cause.",b:"Could there be another explanation?"}]},
{id:"d21",cat:"daily",title:"21. 誘う・断る",items:[{en:"Would you like to get something to eat?",ja:"何か食べに行きませんか？",a:"Are you free now?",b:"Would you like to get something to eat?"},{en:"I would love to, but I already have plans.",ja:"行きたいのですが、すでに予定があります。",a:"Do you want to come with us?",b:"I would love to, but I already have plans."},{en:"Maybe another time.",ja:"また今度にしましょう。",a:"Can you make it today?",b:"Not today. Maybe another time."}]},
{id:"d22",cat:"daily",title:"22. 好みを比べる",items:[{en:"I prefer quieter places.",ja:"私は静かな場所のほうが好きです。",a:"What kind of place do you like?",b:"I prefer quieter places."},{en:"This one is easier to use than the other one.",ja:"こちらのほうがもう一方より使いやすいです。",a:"Which one do you prefer?",b:"This one is easier to use than the other one."},{en:"It depends on what I am doing.",ja:"何をするかによります。",a:"Which do you usually choose?",b:"It depends on what I am doing."}]},
{id:"d23",cat:"daily",title:"23. 近況をたずねる",items:[{en:"How have you been lately?",ja:"最近どうしていますか？",a:"It has been a while.",b:"Yes. How have you been lately?"},{en:"Have you been busy recently?",ja:"最近忙しかったですか？",a:"I have not seen you much.",b:"Have you been busy recently?"},{en:"Things have been pretty good overall.",ja:"全体的にはかなり順調です。",a:"How are things going?",b:"Things have been pretty good overall."}]},
{id:"t21",cat:"travel",title:"21. 切符・乗車変更",items:[{en:"Can I change this ticket to a later train?",ja:"この切符をもっと遅い電車に変更できますか？",a:"What would you like to change?",b:"Can I change this ticket to a later train?"},{en:"Is there a fee to change it?",ja:"変更手数料はかかりますか？",a:"We can change the ticket.",b:"Is there a fee to change it?"},{en:"Which train is the next available one?",ja:"次に乗れる電車はどれですか？",a:"The original train has left.",b:"Which train is the next available one?"}]},
{id:"t22",cat:"travel",title:"22. 写真・観光地で頼む",items:[{en:"Could you take a picture of us?",ja:"私たちの写真を撮ってもらえますか？",a:"Do you need some help?",b:"Could you take a picture of us?"},{en:"Could you get the whole building in the picture?",ja:"建物全体が入るように撮ってもらえますか？",a:"Is this angle okay?",b:"Could you get the whole building in the picture?"},{en:"That looks great. Thank you.",ja:"とてもいいです。ありがとう。",a:"How is the picture?",b:"That looks great. Thank you."}]},
{id:"t23",cat:"travel",title:"23. 薬局で相談する",items:[{en:"Do you have something for a headache?",ja:"頭痛に効くものはありますか？",a:"How can I help you?",b:"Do you have something for a headache?"},{en:"How often should I take this?",ja:"これはどのくらいの間隔で飲めばいいですか？",a:"Here is the medicine.",b:"How often should I take this?"},{en:"Does this make you sleepy?",ja:"これは眠くなりますか？",a:"Do you have any questions about it?",b:"Yes. Does this make you sleepy?"}]},
{id:"w22",cat:"work",title:"22. 異常音の変化を説明する",items:[{en:"There is a clicking noise coming from this area.",ja:"この辺りからカチカチという音がします。",a:"What did you notice?",b:"There is a clicking noise coming from this area."},{en:"The noise gets louder when the machine speeds up.",ja:"機械が速くなると音が大きくなります。",a:"Does the noise change?",b:"The noise gets louder when the machine speeds up."},{en:"It was not making this noise yesterday.",ja:"昨日はこの音はしていませんでした。",a:"Was it doing this yesterday?",b:"No. It was not making this noise yesterday."}]},
{id:"w23",cat:"work",title:"23. 漏れの条件を説明する",items:[{en:"There is a small oil leak near the fitting.",ja:"継手付近に少量の油漏れがあります。",a:"Where is the leak?",b:"There is a small oil leak near the fitting."},{en:"The leak appears only while the machine is running.",ja:"漏れは機械の稼働中だけ現れます。",a:"Does it leak all the time?",b:"No. The leak appears only while the machine is running."},{en:"We need to clean the area before checking it again.",ja:"再確認する前に周辺を清掃する必要があります。",a:"What should we do next?",b:"We need to clean the area before checking it again."}]},
{id:"w24",cat:"work",title:"24. 修理後の確認と記録",items:[{en:"Let's run the machine and watch it for a while.",ja:"機械を動かして、しばらく様子を見ましょう。",a:"Is the repair finished?",b:"Yes. Let's run the machine and watch it for a while."},{en:"Check for leaks, noise, and abnormal temperature.",ja:"漏れ、異音、異常温度を確認してください。",a:"What should I watch for?",b:"Check for leaks, noise, and abnormal temperature."},{en:"Record the readings before we hand it back.",ja:"引き渡す前に測定値を記録してください。",a:"Anything else?",b:"Record the readings before we hand it back."}]},
{id:"a18",cat:"advanced",title:"18. 証拠と推測を分ける",items:[{en:"What we know for sure is that the pressure dropped.",ja:"確実に分かっているのは圧力が低下したことです。",a:"What do we know for certain?",b:"What we know for sure is that the pressure dropped."},{en:"The idea that the valve caused it is still only a hypothesis.",ja:"バルブが原因という考えは、まだ仮説にすぎません。",a:"Is the valve definitely the cause?",b:"No. The idea that the valve caused it is still only a hypothesis."},{en:"We should keep the facts separate from our assumptions.",ja:"事実と推測は分けて考えるべきです。",a:"How should we approach this?",b:"We should keep the facts separate from our assumptions."}]},
{id:"a19",cat:"advanced",title:"19. リスクを比較する",items:[{en:"Restarting now carries a higher risk than waiting another hour.",ja:"今再起動するほうが、あと1時間待つよりリスクが高いです。",a:"Which option is riskier?",b:"Restarting now carries a higher risk than waiting another hour."},{en:"The likelihood is low, but the consequences could be serious.",ja:"可能性は低いですが、結果は重大になり得ます。",a:"Is the risk high?",b:"The likelihood is low, but the consequences could be serious."},{en:"We need to consider both probability and impact.",ja:"発生確率と影響の両方を考える必要があります。",a:"How should we assess the risk?",b:"We need to consider both probability and impact."}]},
{id:"a20",cat:"advanced",title:"20. 次の一手を正当化する",items:[{en:"The next logical step is to verify the pressure reading independently.",ja:"次の論理的な一手は、圧力値を別の方法で確認することです。",a:"What should we do next?",b:"The next logical step is to verify the pressure reading independently."},{en:"That test will help us rule out one of the main possibilities.",ja:"その試験で主要な可能性の1つを除外できます。",a:"Why run that test?",b:"That test will help us rule out one of the main possibilities."},{en:"If the result is normal, we can move on to the valve.",ja:"結果が正常なら、次にバルブを確認できます。",a:"What if the result is normal?",b:"If the result is normal, we can move on to the valve."}]},
{id:"m16",cat:"master",title:"16. その場で構造化して答える",items:[{en:"There are three things we need to consider: safety, time, and evidence.",ja:"考えるべきことは、安全・時間・根拠の3つです。",a:"What should we consider?",b:"There are three things we need to consider: safety, time, and evidence."},{en:"First I will explain what we know, then what we suspect, and finally what we should do.",ja:"まず分かっていること、次に推測、最後に取るべき対応を説明します。",a:"Can you walk me through it?",b:"First I will explain what we know, then what we suspect, and finally what we should do."},{en:"That distinction is important because the action depends on which case is true.",ja:"どちらが正しいかで対応が変わるため、その区別が重要です。",a:"Why does that distinction matter?",b:"That distinction is important because the action depends on which case is true."}]},
{id:"m17",cat:"master",title:"17. 相手の懸念を言語化する",items:[{en:"It sounds like your main concern is the possibility of another shutdown.",ja:"一番の懸念は再停止の可能性ということですね。",a:"Do you understand my concern?",b:"It sounds like your main concern is the possibility of another shutdown."},{en:"If I understand correctly, you want a solution that reduces downtime without increasing risk.",ja:"正しく理解していれば、リスクを増やさず停止時間を減らす解決策を求めているのですね。",a:"What do you think I am asking for?",b:"If I understand correctly, you want a solution that reduces downtime without increasing risk."},{en:"That is a reasonable concern, and we can address it by setting clear stop conditions.",ja:"もっともな懸念です。明確な停止条件を設けることで対応できます。",a:"Can we deal with that risk?",b:"That is a reasonable concern, and we can address it by setting clear stop conditions."}]},
{id:"m18",cat:"master",title:"18. 判断を更新する",items:[{en:"The new measurement changes my assessment.",ja:"新しい測定値によって判断が変わりました。",a:"Does the new data matter?",b:"Yes. The new measurement changes my assessment."},{en:"Given this result, the leak hypothesis is now less likely.",ja:"この結果を踏まえると、漏れの仮説の可能性は下がりました。",a:"Do you still think it is a leak?",b:"Given this result, the leak hypothesis is now less likely."},{en:"We should be willing to revise the plan when the evidence changes.",ja:"証拠が変われば計画を見直すべきです。",a:"Why are we changing the plan?",b:"We should be willing to revise the plan when the evidence changes."}]},
{id:"m19",cat:"master",title:"19. 合意点と未解決点をまとめる",items:[{en:"We agree on the immediate action, but the root cause is still unresolved.",ja:"当面の対応には合意していますが、根本原因はまだ未解決です。",a:"What have we agreed on?",b:"We agree on the immediate action, but the root cause is still unresolved."},{en:"The remaining question is whether the pressure drop is a cause or a symptom.",ja:"残る疑問は、圧力低下が原因なのか症状なのかです。",a:"What is still unclear?",b:"The remaining question is whether the pressure drop is a cause or a symptom."},{en:"Let's document what we know and what still needs to be verified.",ja:"分かっていることと、まだ確認が必要なことを記録しましょう。",a:"What should we do before we finish?",b:"Let's document what we know and what still needs to be verified."}]}
]};